def build_projects():
    known_types={key for key,_,_ in PROJECT_TYPES}
    assert all(project['projectType'] in known_types for project in DATA['projects']), 'Every project needs a valid projectType.'
    navigation=[]
    groups=[]
    for key,label,description in PROJECT_TYPES:
        projects=[project for project in DATA['projects'] if project['projectType']==key]
        slug=key+'-project' if key!='funded' else 'funded-research-project'
        navigation.append(f'<a class="project-category-link" href="#{slug}"><span>{e(label)}</span><span class="project-category-count">{len(projects):02d}</span></a>')
        rows=''.join(project_row(project,number) for number,project in enumerate(projects,1))
        groups.append(f'<section id="{slug}" class="project-group" aria-labelledby="{slug}-title"><div class="project-group-heading"><h2 id="{slug}-title" class="project-group-title">{e(label)}<sup>{len(projects):02d}</sup></h2><p>{e(description)}</p></div><div>{rows}</div></section>')
    body=f'''<section id="projects" class="section" aria-labelledby="projects-title"><div class="section-heading"><div><p class="eyebrow section-kicker">06 / PROJECTS &amp; TOOLS</p><h1 id="projects-title" class="section-title">Projects<sup>{len(DATA['projects']):02d}</sup></h1></div><p>Coursework, research, funded programs, competitions, and independent projects.</p></div><nav class="project-category-nav" aria-label="Project categories">{''.join(navigation)}</nav>{''.join(groups)}<div class="project-links">{external('https://github.com/rohkyoungmin?tab=repositories','GitHub repositories <span aria-hidden="true">â†—</span>','text-link')}</div></section>'''
    write_page('projects.html','Projects','Coursework, research, funded research, competition, personal, and toy projects by Kyoungmin Roh.',body)


def build_participation():
    albums=[]
    photo_index=0
    album_navigation=''.join(f'<a class="album-link" href="#{e(event["id"])}">{e(event["title"])} <span class="album-count">{len(event["photos"]):02d}</span></a>' for event in DATA['participation'])
    for event in DATA['participation']:
        photos=[]
        for number,photo in enumerate(event['photos'],1):
            loading='eager' if number<=4 else 'lazy'
            fetchpriority='high' if photo_index==0 else 'auto'
            position=f' style="object-position:{e(photo["objectPosition"])}"' if photo.get('objectPosition') else ''
            photos.append(f'''<figure class="participation-photo"><a class="photo-open" href="{e(photo['src'])}" data-photo-index="{photo_index}" data-photo-caption="{e(photo['caption'])}" data-photo-album="{e(event['title'])}" aria-label="Open photograph {number}: {e(photo['caption'])}"><img src="{e(photo['src'])}" width="{photo['width']}" height="{photo['height']}" alt="{e(photo['alt'])}" loading="{loading}" decoding="async" fetchpriority="{fetchpriority}"{position}></a><figcaption><span class="mono">{number:02d}</span><span>{e(photo['caption'])}</span></figcaption></figure>''')
            photo_index+=1
        paper_link=external(event['paperUrl'],e(event.get('paperLabel','Paper'))+' â†—','text-link')
        albums.append(f'''<article id="{e(event['id'])}" class="conference-album" aria-labelledby="{e(event['id'])}-title"><div class="conference-heading"><div class="conference-meta"><p class="eyebrow">CONFERENCE / {event['year']}</p><h2 id="{e(event['id'])}-title">{e(event['title'])}</h2><p class="conference-name">{e(event['name'])}</p><p class="mono">{e(event['period'])}<br>{e(event['location'])}</p>{paper_link}</div><div class="conference-summary"><p>{e(event['description'])}</p><p class="mono muted">{len(event['photos']):02d} PHOTOGRAPHS Â· SELECT TO ENLARGE</p></div></div><div class="participation-grid">{''.join(photos)}</div></article>''')
    body=f'''<section id="participation" class="section" aria-labelledby="participation-title"><div class="section-heading"><div><p class="eyebrow section-kicker">10 / GALLERY</p><h1 id="participation-title" class="section-title">Gallery</h1></div><p>Conferences, presentations, and moments from the journey.</p></div><nav class="album-navigation" aria-label="Conference albums">{album_navigation}</nav>{''.join(albums)}</section>
<dialog id="photo-viewer" class="photo-dialog" aria-labelledby="photo-viewer-title" aria-describedby="photo-viewer-caption"><div class="photo-viewer-header"><h2 id="photo-viewer-title">Conference photographs</h2><button type="button" class="photo-close" aria-label="Close photograph" autofocus>Close Ã—</button></div><div class="photo-viewer-body"><button type="button" class="photo-prev" aria-label="Previous photograph">â†</button><img class="photo-viewer-image" alt=""><button type="button" class="photo-next" aria-label="Next photograph">â†’</button></div><p id="photo-viewer-caption" class="photo-viewer-caption"></p><p class="photo-position" role="status" aria-live="polite"></p></dialog>'''
    write_page('participation.html','Gallery','Conference presentations and photographs from KCC 2026 and ACM SAC 2026 by Kyoungmin Roh.',body)
    # Keep old bookmarks working without retaining the former gallery content.
    (ROOT/'gallery.html').write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gallery â€” Kyoungmin Roh</title><meta http-equiv="refresh" content="0;url=participation.html"><link rel="canonical" href="{BASE}/participation.html"><meta name="robots" content="noindex"></head><body><h1>Gallery</h1><p><a href="participation.html">View gallery â†’</a></p></body></html>''')


def build_certificates():
    cards=[]
    for certificate in DATA['certificates']:
        cards.append(f'''<article class="certificate-card" aria-labelledby="{e(certificate['id'])}-title"><div class="certificate-copy"><p class="eyebrow">LANGUAGE PROFICIENCY</p><h2 id="{e(certificate['id'])}-title">{e(certificate['title'])}</h2><p class="mono muted">Test date: <time datetime="{e(certificate['date'])}">{e(certificate['dateLabel'])}</time></p><p class="certificate-score">{e(certificate['summary'])}</p><p>{e(certificate['details'])}</p></div><a class="certificate-image-link" href="{e(certificate['image'])}" target="_blank" rel="noopener noreferrer" aria-label="View full-size {e(certificate['title'])} score report"><img class="certificate-image" src="{e(certificate['image'])}" width="{certificate['width']}" height="{certificate['height']}" alt="{e(certificate['alt'])}" decoding="async"><span class="text-link">View full-size score report â†—</span></a></article>''')
    body=f'''<section id="certificate" class="section" aria-labelledby="certificate-title"><div class="section-heading"><div><p class="eyebrow section-kicker">08 / CERTIFICATE</p><h1 id="certificate-title" class="section-title">Certificate</h1></div><p>Language proficiency and certificates.</p></div><div class="certificate-list">{''.join(cards)}</div></section>'''
    write_page('certificate.html','Certificate','Language proficiency and certificates of Kyoungmin Roh.',body)


def build_extracurricular():
    rows=[]
    for activity in DATA['extracurricular']:
        organization=e(activity['organization'])
        if activity.get('url'):
            organization=external(activity['url'],organization+' â†—')
        rows.append(f'''<article class="activity-row"><p class="mono activity-period">{e(activity['period'])}</p><div class="activity-heading"><h2>{e(activity['title'])}</h2><p class="activity-role">{e(activity['role'])}</p><p class="activity-organization">{organization}</p></div><p class="activity-description">{e(activity['description'])}</p></article>''')
    body=f'''<section id="extracurricular" class="section" aria-labelledby="extracurricular-title"><div class="section-heading"><div><p class="eyebrow section-kicker">09 / EXTRACURRICULAR</p><h1 id="extracurricular-title" class="section-title">Extracurricular</h1></div><p>Clubs, cybersecurity activities, writing, and campus life.</p></div><div class="activity-list">{''.join(rows)}</div></section>'''
    write_page('extracurricular.html','Extracurricular','Clubs, cybersecurity activities, writing, and campus life of Kyoungmin Roh.',body)


def build_cases():
    folder=ROOT/'research'
    folder.mkdir(exist_ok=True)
    for i,case in enumerate(DATA['caseStudies']):
        slug=case['id']
        text=head(case['title']+' â€” Kyoungmin Roh',case['subtitle'],f'research/{slug}.html','../',active='projects.html')
        meta=''.join(f'<div><span class="mono muted">{label}</span><p>{e(case[key])}</p></div>' for label,key in [('AREA','category'),('PERIOD','year'),('ROLE','role'),('STATUS','status')])
        blocks=''.join(f'<section class="case-section"><h2>{label}</h2><p>{e(case[key])}</p></section>' for label,key in [('Problem','problem'),('Approach','approach'),('Contribution','contribution'),('Results','outcome'),('Scope & limitations','limits')])
        resources=''.join(external(link['url'],e(link['label'])+' <span aria-hidden="true">â†—</span>','pill-link') for link in case['links'])
        next_case=DATA['caseStudies'][(i+1)%len(DATA['caseStudies'])]
        text+=f'''<main id="main" class="wrap"><section class="case-hero"><a href="../publications.html" class="back-link"><span aria-hidden="true">â†</span> Publications</a><h1 class="case-title">{e(case['title'])}</h1><p class="case-subtitle">{e(case['subtitle'])}</p><div class="case-meta">{meta}</div></section><figure class="case-art" style="margin:0"><img src="../assets/{slug}.svg" width="1600" height="1100" alt="Conceptual illustration for {e(case['title'])}"><figcaption class="art-caption">Conceptual illustration</figcaption></figure><div class="case-body">{blocks}<section class="case-section"><h2>Resources</h2><div class="case-resource-links">{resources}</div></section></div><section class="next-case"><a href="{next_case['id']}.html"><div><span class="eyebrow">NEXT PROJECT</span><h2>{e(next_case['title'])}</h2></div><span class="arrow" aria-hidden="true">â†—</span></a></section></main>'''
        text+=footer('../')
        (folder/f'{slug}.html').write_text(text)

def build_support():
    (ROOT/'.nojekyll').write_text('')
    (ROOT/'robots.txt').write_text(f'User-agent: *\nAllow: /\nSitemap: {BASE}/sitemap.xml\n')
    urls=[BASE+'/']+[BASE+'/'+route for route,_,_ in PAGES[1:]]+[BASE+'/research/'+case['id']+'.html' for case in DATA['caseStudies']]
    (ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{url}</loc></url>' for url in urls)+'</urlset>\n')
    text=head('Page not found â€” Kyoungmin Roh','Return to Kyoungmin Rohâ€™s research portfolio.','404.html','/')
    text+='''<main id="main" class="wrap not-found"><p class="eyebrow">PAGE NOT FOUND</p><h1>404.</h1><p>This page may have moved. Explore the latest research, publications, and projects from the homepage.</p><a class="pill-link" href="/">Return home <span aria-hidden="true">â†—</span></a></main>'''
    text+=footer('/')
    text=text.replace('<link rel="canonical" href="'+BASE+'/404.html">','<meta name="robots" content="noindex">')
    (ROOT/'404.html').write_text(text)

if __name__=='__main__':
    build_home()
